css:
.flank{position:relative;padding:80px 0;background:#7d2b2b}
.flank__body{width:min(560px,46%);margin-inline:auto}
.flank__l{position:absolute;left:2%;top:22%;width:130px}
.flank__r{position:absolute;right:2%;top:30%;width:150px}  /* 左右で高さをずらす */
.flank__lead{display:flex;align-items:center;justify-content:center;gap:32px}
.flank__lead svg{fill:none;stroke-width:1.5;width:34px}
.flank__lead svg:first-child{stroke:#6fb3a8}
.flank__lead svg:last-child{stroke:#d98b7a}
@media(max-width:768px){.flank__body{width:86%}.flank__l,.flank__r{position:static;width:90px}}
